from itertools import product
def fitpoly(deg):
    cols=[];names=[]
    for i,j in product(range(deg+1),repeat=2):
        if i+j<=deg:
            cols.append(A**i*t**j); names.append(f"A^{i} t^{j}")
    X=np.column_stack(cols)
    c,*_=np.linalg.lstsq(X,dA_dt,rcond=None)
    r=dA_dt-X@c
    return np.mean(r**2)/np.var(dA_dt), dict(zip(names,np.round(c,3)))
