import numpy as np
from scipy.optimize import curve_fit
for lo,hi in [(0.2,0.4),(0.9,1.1),(1.9,2.1),(2.7,2.9),(3.2,3.4)]:
    m=(A>=lo)&(A<hi)
    T=t[m];R=dA_dt[m]
    out=[]
    for k,(f,p0) in {'expsq':(lambda t,a,b: a*np.exp(-b*t*t),[10,0.01]),'lin':(lambda t,a,b:a-b*t,[10,0.5]),'quad':(lambda t,a,b,c:a-b*t+c*t*t,[10,0.5,0.0])}.items():
        try:
            p,_=curve_fit(f,T,R,p0=p0,maxfev=20000)
            out.append((k,np.round(p,4).tolist(),float('%.2e'%(np.mean((R-f(T,*p))**2)/np.var(R)))))
        except Exception as e: out.append((k,str(e)[:30]))
    print(lo,hi,m.sum(),out)
